FTOF=formula('d = c t / 2',{'d':'one-way sensor-to-object distance','c':'propagation speed of light, approximated as 3 × 10^8 m/s','t':'round-trip flight time'},{'d':'m','c':'m/s','t':'s'},['Pulsed time-of-flight model; convert nanoseconds to seconds.'])
FENC=formula('s = n (2πr/N)',{'s':'estimated rolling distance','n':'measured pulse count','r':'wheel radius','N':'pulses per full revolution'},{'s,r':'m','n,N':'dimensionless counts'},['Calibrated encoder and rolling without slip.'])
FBAYES=formula('b̄_i = Σ_j T_ij b_j; b_i = ℓ_i b̄_i / Σ_k ℓ_k b̄_k',{'b_j':'previous discrete-state probability for state j','b̄_i':'predicted probability for state i','b_i':'corrected probability for state i','T_ij':'transition probability to i from j under the current control','ℓ_i':'likelihood of the observed measurement at state i','i,j,k':'state indices'},{'b_j,b̄_i,b_i,T_ij,ℓ_i,i,j,k':'dimensionless in this discrete example'},['Columns of T sum to 1; Markov transition and conditionally independent observation; positive evidence denominator.'])
FKF=formula('μ̄ = Fμ + Gu; P̄ = FPFᵀ + V; S = HP̄Hᵀ + W; K = P̄HᵀS⁻¹; μ⁺ = μ̄ + K(z − Hμ̄); P⁺ = (I − KH)P̄',{'μ,P':'previous corrected state mean and covariance','μ̄,P̄':'predicted mean and covariance','μ⁺,P⁺':'new corrected mean and covariance','F':'state transition matrix','G':'control input matrix','u':'known control input','V':'process-noise covariance in state coordinates','H':'measurement matrix','W':'measurement-noise covariance','z':'new measurement','S':'innovation covariance','K':'Kalman gain','I':'state-space identity matrix'},{'μ,μ̄,μ⁺':'state units componentwise','P,P̄,P⁺,V':'products of the corresponding state-component units','z':'measurement units componentwise','S,W':'products of measurement-component units','F,G,H,K':'mapping units required by their domains and codomains','u':'declared control units','I':'dimensionless'},['Linear models; known deterministic control; mutually independent zero-mean process/measurement noise and initial error; nonsingular S.'])
FGAUSS=formula('p(x) = exp(−(x−μ)ᵀΣ⁻¹(x−μ)/2) / ((2π)^(n/2) sqrt(det Σ))',{'x':'n-dimensional state vector','μ':'Gaussian mean vector','Σ':'state covariance matrix','n':'state dimension','p(x)':'probability density','det':'matrix determinant'},{'x,μ':'state units componentwise','Σ':'products of state-component units','n':'dimensionless','p(x)':'inverse product of state-coordinate units'},['Σ symmetric positive definite for this ordinary density formula.'])
